/** Real registry-aware native item codecs and DFU, including dynamic enchantment lookups. */
@EventBusSubscriber(modid="vandorlabs")
public final class StorageItemCodecChecks {
 private static int checks;private static void need(boolean yes,String why){checks++;if(!yes)throw new AssertionError("Storage codec: "+why);}
 private static void run(ServerLevel level)throws Exception{JsonObject source;try(var stream=new GZIPInputStream(Files.newInputStream(Path.of(System.getProperty("vandorlabs.storageItemReference"))));var reader=new InputStreamReader(stream,java.nio.charset.StandardCharsets.UTF_8)){source=JsonParser.parseReader(reader).getAsJsonObject();}need(source.get("sourceDataVersion").getAsInt()==NativeInventoryItems.SOURCE_DATA_VERSION,"actual Source runtime data version");var sourceIds=new java.util.HashSet<String>();for(var id:source.getAsJsonArray("vanillaItems"))sourceIds.add(id.getAsString());need(sourceIds.equals(NativeInventoryItems.sourceVanillaItems()),"all actual Source vanilla item IDs");int accepted=0,refused=0;for(var value:source.getAsJsonArray("cases")){var row=value.getAsJsonObject();String label=row.get("label").getAsString();var raw=TagParser.parseTag(row.get("raw").getAsString());var before=raw.copy();boolean supported=java.util.Set.of("plain","metadata-name","durability-enchantment","named-sword","written-book","container","shulker-container","actual-shulker-drop","credential","nested-credential").contains(label);try{var stack=NativeInventoryItems.legacy(raw,level.registryAccess());need(supported,"unsupported ownership accepted "+label);need(stack.getCount()==row.get("count").getAsInt(),"Source count "+label);var encoded=NativeInventoryItems.write(stack,level.registryAccess());need(net.minecraft.world.item.ItemStack.isSameItemSameComponents(stack,NativeInventoryItems.modern(encoded,level.registryAccess())),"real native codec roundtrip "+label);switch(label){case "metadata-name"->need(stack.is(net.minecraft.world.item.Items.GRANITE)&&stack.getHoverName().getString().equals("Legacy granite"),"metadata/name migration");case "durability-enchantment"->{need(stack.getDamageValue()==41,"durability");need(encoded.getCompound("components").getCompound("minecraft:enchantments").getCompound("levels").getInt("minecraft:efficiency")==3,"actual dynamic enchantment codec");}case "named-sword"->{need(stack.getDamageValue()==13&&stack.getHoverName().getString().equals("Legacy blade"),"named durable sword");need(stack.get(DataComponents.LORE).lines().size()==2,"lore migration");need(encoded.getCompound("components").getCompound("minecraft:enchantments").getCompound("levels").getInt("minecraft:sharpness")==5,"named enchantment");}case "credential"->need(com.vandorlabs.neoforge.credentials.NativeCredentialItems.company(stack)==2&&com.vandorlabs.neoforge.credentials.NativeCredentialItems.legacyCredentialData(stack).equals(raw),"proven credential retains opaque original");case "nested-credential"->{var nested=stack.get(DataComponents.CONTAINER).getStackInSlot(0);need(com.vandorlabs.neoforge.credentials.NativeCredentialItems.company(nested)==2&&com.vandorlabs.neoforge.credentials.NativeCredentialItems.legacyCredentialData(nested).getCompound("ForgeCaps").contains("foreign:chip"),"nested credential staged before vanilla parent conversion");}case "written-book"->need(stack.get(DataComponents.WRITTEN_BOOK_CONTENT)!=null,"written book component");case "container","shulker-container","actual-shulker-drop"->{var entries=encoded.getCompound("components").getList("minecraft:container",Tag.TAG_COMPOUND);need(entries.size()==1&&entries.getCompound(0).getCompound("item").getInt("count")== (label.equals("container")?9:3),"nested physical item preserved "+label);}default->{}}accepted++;}catch(RuntimeException failure){if(supported)throw new IllegalStateException("Supported Source item "+label,failure);refused++;}need(raw.equals(before),"original item snapshot untouched "+label);}var zeroCaps=TagParser.parseTag("{id:\"minecraft:iron_ingot\",Count:0b,ForgeCaps:{\"foreign:owned\":{Marker:7}}}");boolean zeroRefused=false;try{NativeInventoryItems.legacy(zeroCaps,level.registryAccess());}catch(IllegalArgumentException expected){zeroRefused=true;}need(zeroRefused,"zero-count item must not erase opaque capability owner");var unknownNested=TagParser.parseTag("{id:\"minecraft:chest\",count:1,components:{\"minecraft:container\":[{slot:0,item:{id:\"missing:owned\",count:1}}]}}");boolean nestedRefused=false;try{NativeInventoryItems.modern(unknownNested,level.registryAccess());}catch(RuntimeException expected){nestedRefused=true;}need(nestedRefused,"actual native codec refuses unknown nested item ownership");var futureSlot=TagParser.parseTag("{id:\"minecraft:chest\",count:1,components:{\"minecraft:container\":[{slot:0,item:{id:\"minecraft:iron_ingot\",count:1},FutureInventory:{Items:[]}}]}}");boolean futureRefused=false;try{NativeInventoryItems.modern(futureSlot,level.registryAccess());}catch(RuntimeException expected){futureRefused=true;}need(futureRefused,"unknown native nested ownership cannot disappear through permissive codec");var deep=TagParser.parseTag("{id:\"minecraft:iron_ingot\",count:1}");for(int i=0;i<33;i++){var parent=TagParser.parseTag("{id:\"minecraft:chest\",count:1}");var component=new CompoundTag();var list=new ListTag();var slot=new CompoundTag();slot.putInt("slot",0);slot.put("item",deep);list.add(slot);component.put("minecraft:container",list);parent.put("components",component);deep=parent;}boolean deepRefused=false;try{NativeInventoryItems.modern(deep,level.registryAccess());}catch(IllegalArgumentException expected){deepRefused=true;}need(deepRefused,"native nested item depth refuses before codec recursion");boolean unmarkedRefused=false;try{NativeInventoryItems.legacy(TagParser.parseTag("{id:\"minecraft:diamond\",count:3}"),level.registryAccess());}catch(IllegalArgumentException expected){unmarkedRefused=true;}need(unmarkedRefused,"unmarked modern owner must not appear as empty legacy Count");need(accepted==10&&refused==7,"Source item corpus coverage");System.out.println("[vandorlabs][storage-codec] PASS checks="+checks+" accepted="+accepted+" refused="+refused+" actual native registry/DFU/name/damage/enchantment/container codecs");}
 @SubscribeEvent public static void started(ServerStartedEvent event){if(!"storage-codec".equals(System.getProperty("vandorlabs.transmitterPhase")))return;try{run(event.getServer().overworld());}catch(Throwable failure){failure.printStackTrace();System.out.println("[vandorlabs][storage-codec] FAIL "+failure);}finally{event.getServer().halt(false);}}
}
